//! The generated per-code-point property records, and the [`Record`] type they
//! populate.

use super::enums::{
    BidiClass, Block, Category, ClusterBreak, JoiningType, LineBreak, MyanmarClass, Script,
    UseClass, WordBreak,
};

#[derive(Copy, Clone)]
pub struct Record {
    pub flags: Flags,
    pub category: Category,
    pub block: Block,
    pub script: Script,
    pub combining_class: u8,
    pub bidi_class: BidiClass,
    pub joining_type: JoiningType,
    pub cluster_break: ClusterBreak,
    pub word_break: WordBreak,
    pub line_break: LineBreak,
    pub use_class: UseClass,
    pub myanmar_class: MyanmarClass,
}

#[derive(Copy, Clone)]
#[repr(transparent)]
pub struct Flags(pub u8);

impl Flags {
    pub fn is_emoji(self) -> bool {
        self.0 & 1 != 0
    }

    pub fn is_extended_pictographic(self) -> bool {
        self.0 & 2 != 0
    }

    pub fn is_open_bracket(self) -> bool {
        self.0 & 4 != 0
    }

    pub fn is_close_bracket(self) -> bool {
        self.0 & 8 != 0
    }

    pub fn is_variation_selector(self) -> bool {
        self.0 & 16 != 0
    }

    pub fn is_ignorable(self) -> bool {
        self.0 & 32 != 0
    }

    pub fn contributes_to_shaping(self) -> bool {
        self.0 & 64 != 0
    }

    pub fn needs_decomp(self) -> bool {
        self.0 & 128 != 0
    }
}

const fn r(
    flags: u8,
    category: Category,
    block: Block,
    script: Script,
    combining_class: u8,
    bidi_class: BidiClass,
    joining_type: JoiningType,
    cluster_break: ClusterBreak,
    word_break: WordBreak,
    line_break: LineBreak,
    use_class: UseClass,
    myanmar_class: MyanmarClass,
) -> Record {
    Record {
        flags: Flags(flags),
        category,
        block,
        script,
        combining_class,
        bidi_class,
        joining_type,
        cluster_break,
        word_break,
        line_break,
        use_class,
        myanmar_class,
    }
}

